import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_LIMIT = 21;
    static final double TOL = 1e-6;
    static int count_m = 0, k_req, total_m;
    static double[] probs = new double[MAX_LIMIT];
    static int[] order = new int[MAX_LIMIT];
    static double[] output = new double[MAX_LIMIT];
    static double[] dp_state = new double[1 << MAX_LIMIT];

    static void read_input(Scanner sc) {
        total_m = sc.nextInt();
        k_req = sc.nextInt();
        for (int i = 0; i < total_m; i++) {
            double val = sc.nextDouble();
            if (val > TOL) {
                probs[count_m] = val;
                order[count_m] = i;
                count_m++;
            } else {
                output[i] = 0;
            }
        }
    }

    static void process() {
        if (k_req >= count_m) {
            for (int i = 0; i < count_m; i++) {
                output[order[i]] = 1.0;
            }
        } else {
            Arrays.fill(dp_state, 0.0);
            dp_state[0] = 1.0;
            int total_subsets = 1 << count_m;
            for (int mask = 0; mask < total_subsets; mask++) {
                if (Integer.bitCount(mask) < k_req) {
                    double sum_prob = 0.0;
                    for (int t = 0; t < count_m; t++) {
                        if (((mask >> t) & 1) == 0) {
                            sum_prob += probs[t];
                        }
                    }
                    if (sum_prob > 0) {
                        for (int t = 0; t < count_m; t++) {
                            if (((mask >> t) & 1) == 0) {
                                int next_mask = mask | (1 << t);
                                dp_state[next_mask] += (probs[t] / sum_prob) * dp_state[mask];
                            }
                        }
                    }
                }
            }
            for (int mask = 0; mask < total_subsets; mask++) {
                if (Integer.bitCount(mask) == k_req) {
                    for (int t = 0; t < count_m; t++) {
                        if (((mask >> t) & 1) == 1) {
                            output[order[t]] += dp_state[mask];
                        }
                    }
                }
            }
        }
        for (int i = 0; i < total_m; i++) {
            System.out.print(output[i] + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        read_input(sc);
        process();
        sc.close();
    }
}
